    getV1Feedbacks(isAnswered: boolean, take: number, skip: number, nmId?: number, order?: GetV1FeedbacksOrderEnum, dateFrom?: number, dateTo?: number, options?: RawAxiosRequestConfig): AxiosPromise<GetV1FeedbacksResponse200>;

